    "description": "KAIST is South Korea's leading specialised science and technology research university, globally recognized for its excellence in engineering and AI.",
    "overviewLong": "Established in 1971 as the nation's premier research-oriented science and engineering institution with funding and advisory support from USAID, KAIST (Korea Advanced Institute of Science and Technology) in Daejeon's Daedeok Innopolis is South Korea's top technological research university (#65 globally in the QS World University Rankings 2027 and #2 nationwide). As the primary engine of South Korea's miraculous post-war economic transformation—the 'Miracle on the Han River'—KAIST has educated the technological leaders who founded and architected South Korea's semiconductor, telecommunications, robotics, and internet industries (including Nexon, Naver, Kakao, and leadership at Samsung Electronics).\n\nKAIST's scientific firepower is world-class: its Engineering and Technology faculty ranks among the world's top 15 (#14 globally in Materials Science, #15 in Chemical Engineering, #17 in Mechanical & Aeronautical Engineering, #19 in Electrical Engineering, and #22 in Computer Science). KAIST is famous as the home of HUBO, the world-champion disaster-response humanoid robot that triumphed in the DARPA Robotics Challenge. Under Distinguished Professor Sang Yup Lee, KAIST founded systems metabolic engineering, synthesizing spider silk and bio-based plastics from microbial cell factories. Furthermore, KAIST houses the Kim Jaechun Graduate School of AI, the National NanoFab Center (NNFC), and the Satellite Technology Research Center (SaTReC), which developed KITSAT-1, Korea's first satellite.\n\nKAIST operates a virtually unrivaled global admissions policy: 100% of admitted international undergraduate and graduate students receive comprehensive institutional financial coverage. Admitted undergraduates receive the KAIST International Student Scholarship (KISS), granting a full 4-year tuition waiver (KRW 6,860,000/year), a monthly living stipend of KRW 350,000, and comprehensive National Health Insurance coverage. Graduate researchers receive 100% tuition coverage plus institutional stipends combined with laboratory Research Assistantships (RA), frequently yielding monthly stipends between KRW 1,000,000 and KRW 1,500,000.",
