    "overviewLong": "Established in 1986 by POSCO founding chairman Tae-Joon Park and modeled directly on the world's finest technological institutes like Caltech, POSTECH (Pohang University of Science and Technology) in Pohang, Gyeongsangbuk-do, is South Korea's premier elite private science and technology university (#106 globally in the QS World University Rankings 2027 and top 4 nationwide). Operating with an ultra-selective student-to-faculty ratio of approximately 3:1, POSTECH cultivates an intimate, immersive research ecosystem that guarantees 100% undergraduate access to real frontline laboratory investigation from their freshman year.\n\nPOSTECH is globally renowned for its monumental scientific infrastructure: it owns and operates the Pohang Accelerator Laboratory, housing the Pohang Light Source (PLS-II, a 3rd-generation synchrotron) and the PAL-XFEL (a 4th-generation X-ray free-electron laser)—one of only five such ultra-advanced femtosecond molecular imaging facilities operating globally. In Materials Science (#30 worldwide in QS 2026), POSTECH's Graduate Institute of Ferrous & Energy Materials Technology (GIFT) leads world advancements in ultra-high-strength steel alloys, solid-state battery electrolytes, high-entropy metallurgy, and quantum materials. Furthermore, POSTECH collaborates intimately with POSCO and the Max Planck POSTECH/Korea Research Initiative in nanoscience and quantum condensed matter.\n\nPOSTECH operates a full-funding commitment for international talent: admitted undergraduate international scholars receive 100% tuition coverage for 8 semesters (KRW 6,000,000/year), monthly living stipends of KRW 350,000 to KRW 500,000, and subsidized campus dormitory lodging. Graduate research scholars (Master's and PhD) receive 100% tuition coverage alongside laboratory Graduate Research Assistantships (GRA) delivering guaranteed monthly stipends of KRW 1,000,000 to KRW 1,600,000+.",
