    "overviewLong": "Founded in 1559 by Protestant reformer John Calvin as a theological and humanistic academy (*Schola Genevensis*), the University of Geneva (Université de Genève or UNIGE) is Switzerland's third-oldest university and a world-renowned comprehensive research institution (#128 globally in QS 2027, #58 globally in ARWU 2025). Situated across multiple urban campus buildings in Geneva—including Uni Bastions, Uni Dufour, Uni Mail, and the Sciences I & II complexes along the Arve River—UNIGE educates over 19,000 students from 150 nations.\n\nUNIGE holds elite global research rankings across physical sciences, mathematics, life sciences, and international law, ranking #15 globally in Physics, #28 in Mathematics, #31 in Dentistry, and #41 in Medical Technology in ShanghaiRanking 2025. Its proximity to international headquarters—including the United Nations European Office, WHO, WTO, CERN, and the ICRC—makes UNIGE a global leader in international relations, global health, climate law, and astrophysics (where UNIGE astronomers Michel Mayor and Didier Queloz discovered the first exoplanet, winning the 2019 Nobel Prize in Physics).\n\nUNIGE maintains low standard tuition fees of only CHF 500 per semester (CHF 1,000 per year) for both domestic and international students. Outstanding international Master's candidates applying to the Faculty of Science or International Relations can secure the UNIGE Excellence Master Fellowship, providing CHF 10,000 to CHF 15,000 per year in merit funding.",
